'use strict';
// Array.prototype.concat spreads an argument that is an array at run time and
// appends any other value, whatever the static type says.
function run(raw) {
  const parsed = JSON.parse(raw);
  let output = ['Usage:', ''];
  output = output.concat([parsed.text, '']);
  output = output.concat(parsed.list);
  output = output.concat(parsed.text);
  return output.join('|') + ' ' + output.length;
}
module.exports = { run };
